function quickSort(array) {
  function swap(a, b) {
    let temp = array[a];
    array[a] = array[b];
    array[b] = temp;
  }

  function partition(arr, l, h) {
    let pivot = arr[h];
    let i = l - 1;

    for (let j = l; j <= h - 1; j++) {
      if (arr[j] < pivot) {
        i++;
        swap(i, j);
      }
    }
    swap(i + 1, h);
    return i + 1;
  }

  function sort(arr, l, h) {
    if (l < h) {
      let pi = partition(arr, l, h);
      sort(arr, l, pi - 1);
      sort(arr, pi + 1, h);
    }
  }

  sort(array, 0, array.length - 1);
  return array;
}

